        sorted_scores = sorted(answer_scores.values(), key=lambda x: x["combined"], reverse=True)
        top_score = sorted_scores[0]["combined"]
        second_score = sorted_scores[1]["combined"] if len(sorted_scores) > 1 else 0

        # Uncertainty: how close are the top two answers?
        uncertainty = 1.0 - (top_score - second_score) / (top_score + 1.0)
        uncertainty_by_qid[qid] = uncertainty

    # Phase 3: Adaptive resampling
    if budget > 0:
        uncertain = sorted(uncertainty_by_qid.items(), key=lambda x: -x[1])

        for qid, uncertainty in uncertain:
            if budget <= 0:
                break

            # Only resample if genuinely uncertain
            if uncertainty < 0.3:  # High confidence
                continue

            # Allocate samples proportional to uncertainty
            if uncertainty > 0.7:
                num_resamples = min(5, budget)
            elif uncertainty > 0.5:
                num_resamples = min(3, budget)
            else:
                num_resamples = min(2, budget)

            for i in range(num_resamples):
                if budget <= 0:
                    break
                variant = i % env.n_variants
                answer, score = env.sample(qid, variant)
                samples_by_qid[qid].append((answer, score))
                budget -= 1

        # Recompute answers with all samples
        for q in env.questions:
            qid = q["id"]
            samples = samples_by_qid[qid]

            if not samples:
                continue

            answer_data = {}
            for answer, score in samples:
                if answer not in answer_data:
                    answer_data[answer] = {"count": 0, "scores": [], "score_sum": 0}
                answer_data[answer]["count"] += 1
                answer_data[answer]["scores"].append(score)
                answer_data[answer]["score_sum"] += score

            answer_scores = {}
            for answer, data in answer_data.items():
                score_weight = data["score_sum"]
                count_weight = data["count"]
                combined = score_weight + count_weight * 0.1
                answer_scores[answer] = combined

            best_answer = max(answer_scores.items(), key=lambda x: x[1])[0]
            answers_by_qid[qid] = best_answer

    # Ensure all questions have answers
    for q in env.questions:
        if q["id"] not in answers_by_qid:
            answers_by_qid[q["id"]] = "0"

    env.submit(answers_by_qid)
